// Site globals for the ported floating tools (study tutor + selection toolbar, translator, structure chips,
// sentence-part colours, media keys, Tab jump). Those scripts are ported from the site almost verbatim
// (tools/*.js, generated by the scratchpad port_tools.py); this module gives them what the site page gave
// them: a live `S`, saveData/render, apiRequest, premium check, favourites and the plan notebook (TDM).
//
// State rules (same as the rest of the app): keys the lesson engine keeps in its draft are read and written
// through the engine, everything else through a short-lived draft that saveData() turns into per-path PATCHes.
// Only keys the site itself persists are ever written; helper keys (favoriteRenderCache …) stay in memory.

import { lang } from './i18n.js';
import { esc } from './ui.js';
import { normalizeFavorite as normFav, deckAddStore, rememberErrorStore, today } from './learning.js';
import { ENGINE_KEYS } from './engine.js';
import { confirmDialog } from '../pages/widgets.js';

const PERSIST = new Set(['favorites', 'errors', 'appSettings', 'wordProgress', 'answerPerformance', 'user', 'testdafMethod', 'oesdMethod']);
const clone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));

/**
 * @param {object} app  { store, bridge, account(), engine() (may be null), page() → page id,
 *                        lesson() → { open, contextInfo(), lookupWord(text), audioSeek(s), audioToggle() } | null,
 *                        navigate(id), refreshChrome(), applyLook() }
 */
export function createSiteShim(app) {
  const own = {};       // drafts of persisted keys the engine does not hold
  const loaded = {};    // JSON of each draft as read from the store (unchanged drafts are dropped on store changes)
  const scratch = {};   // in-memory helper keys (never saved)
  const eng = () => { try { return app.engine(); } catch { return null; } };
  const engineKey = (k) => ENGINE_KEYS.includes(k) && !!eng();

  const SCREEN = () => {
    const id = app.page() || '';
    if (id === 'dashboard') { const l = app.lesson(); return l && l.open ? 'methodActivity' : 'dashboard'; }
    return id;
  };
  const S = new Proxy({}, {
    get(_, k) {
      if (typeof k !== 'string') return undefined;
      if (k === 'uiLanguage') return lang();
      if (k === 'currentUser') { const a = app.account(); return a && a.email ? { email: a.email, name: a.name } : null; }
      if (k === 'screen') return SCREEN();
      if (k === 'accountId') { const a = app.account(); return a && a.id ? String(a.id) : null; }
      if (k === 'dark') return document.documentElement.dataset.theme === 'dark';
      if (k === 'activeActivity') { const l = app.lesson(); return l && l.open ? l.activity() : null; }
      if (PERSIST.has(k)) {
        if (engineKey(k)) return eng().S[k];
        if (!(k in own)) { own[k] = clone(app.store.get(k)); loaded[k] = JSON.stringify(own[k] ?? null); }
        return own[k];
      }
      return scratch[k];
    },
    set(_, k, v) {
      if (typeof k !== 'string' || ['uiLanguage', 'currentUser', 'screen', 'activeActivity', 'accountId', 'dark'].includes(k)) return true;
      if (PERSIST.has(k)) { if (engineKey(k)) eng().S[k] = v; else own[k] = v; } else scratch[k] = v;
      return true;
    },
    has(_, k) { return typeof k === 'string'; },
  });

  function saveData() {
    const e = eng(); if (e) e.save();
    Object.keys(own).forEach((k) => {
      if (JSON.stringify(own[k] ?? null) !== JSON.stringify(app.store.get(k) ?? null)) app.store.set(k, clone(own[k]));
      delete own[k]; delete loaded[k];
    });
  }
  // a draft nobody changed must never outlive a newer store value (it would be written back stale)
  app.store.subscribe((paths) => {
    Object.keys(own).forEach((k) => {
      if (!(paths.includes('*') || paths.some((p) => p === k || p.startsWith(k + '.')))) return;
      if (JSON.stringify(own[k] ?? null) === loaded[k]) { delete own[k]; delete loaded[k]; }
    });
  });
  // site render(): the tools only need the chrome (badges) refreshed and their own hooks to run
  function render() { app.refreshChrome(); }
  const hasPremiumAccess = () => { const a = app.account() || {}; return !!(a.premium || a.admin || a.owner || ['premium', 'admin', 'owner'].includes(a.role)); };
  const openPremiumPlans = () => app.navigate('settings');
  const navigateApp = (id) => app.navigate(id);
  // site roles: owner = the owner role on the owner's own address (site isOwnerAccount), admin = admin or owner
  const role = () => { const a = app.account() || {}; return a.owner ? 'owner' : a.admin ? 'admin' : a.premium ? 'premium' : 'normal'; };
  const isOwnerAccount = () => role() === 'owner' && String((app.account() || {}).email || '').trim().toLowerCase() === 'tah3in@gmail.com';
  const isGlobalContentAdmin = () => ['admin', 'owner'].includes(role());
  const appConfirm = (text) => confirmDialog(String(text || ''), { ok: lang() === 'fa' ? 'تأیید' : lang() === 'en' ? 'OK' : 'OK', danger: false });
  /** site rememberLearningError: into «اشتباهات» with the site's review-worthiness rules */
  function rememberLearningError(err) { const e = eng(); if (e) e.save(); const r = rememberErrorStore(app.store, err); try { if (r && e && e.lean && e.lean()) e.leanErrToDeck(err); } catch (x) { console.warn(x); } return r; }
  const safeText = (v) => esc(v == null ? '' : v);
  const ownerAIClientMessageId = () => (crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(16).slice(2));
  const authTokens = () => ({ access_token: 'app' }); // the main process adds the real token
  function setAppSetting(key, value) { if (!S.appSettings) S.appSettings = {}; S.appSettings[key] = value; saveData(); app.applyLook(); render(); }
  const normalizeFavorite = (item) => normFav(item, app.store.data);
  function favoriteRating(id) { const f = (S.favorites || []).find((x) => x.id === id); return f ? Math.max(1, Math.min(3, Number(f.rating) || 1)) : 0; }
  function setFavoriteRating(id, rating) {
    S.favorites = S.favorites || []; rating = Math.max(1, Math.min(3, Number(rating) || 1));
    const index = S.favorites.findIndex((item) => item.id === id);
    if (index >= 0 && favoriteRating(id) === rating) S.favorites.splice(index, 1);
    else if (index >= 0) S.favorites[index] = { ...normalizeFavorite(S.favorites[index]), rating };
    else { const item = S.favoriteRenderCache?.[id]; if (!item) return; S.favorites.unshift({ ...item, rating, savedAt: new Date().toISOString() }); }
    saveData(); render();
  }
  /** site apiRequest(path, {method, body: JSON string}) → data, or throws {status, details}. */
  function apiRequest(path, opts = {}) {
    return app.bridge.api('/v1' + path, { method: opts.method || 'GET', body: opts.body ? JSON.parse(opts.body) : undefined, timeout: 100000 }).then((r) => {
      if (r && r.ok) return r.data;
      const e = new Error((r && r.error && r.error.message) || 'request failed');
      e.status = r && r.error && r.error.status; e.details = r && r.error && r.error.details;
      throw e;
    });
  }
  /** fetch() for the coach service (/coach/api/…): goes through the main process (gate + token), binary for speech. */
  async function shimFetch(url, opts = {}) {
    const u = String(url);
    if (!u.startsWith('/coach/api/')) return window.fetch(url, opts);
    const binary = /\/tts$/.test(u);
    const r = await app.bridge.api(u, { method: opts.method || 'GET', body: opts.body ? JSON.parse(opts.body) : undefined, binary, timeout: 45000 });
    const status = r && r.ok ? 200 : (r && r.error && r.error.status) || 0;
    return {
      ok: !!(r && r.ok), status,
      json: async () => (r && r.data) || {},
      blob: async () => { const d = (r && r.data) || {}; const bin = atob(d.base64 || ''); const bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i); return new Blob([bytes], { type: d.type || 'audio/mpeg' }); },
    };
  }
  // the plan notebook + lesson context the tools read through window.TDM on the site
  const TDM = {
    deckAddEntry: (type, data) => deckAddStore(app.store, type, data),
    lookupWord: (text) => { const l = app.lesson(); return l ? l.lookupWord(text) : null; },
    contextInfo: () => { const l = app.lesson(); return l && l.open ? l.contextInfo() : null; },
    audioSeek: (s) => { const l = app.lesson(); if (l) l.audioSeek(s); },
    audioToggle: () => { const l = app.lesson(); if (l) l.audioToggle(); },
    active: () => { const e = eng(); return !!(e && e.active()); },
    enrolled: () => { const e = eng(); return !!(e && e.enrolled()); },
    studyMode: () => { const e = eng(); return e ? e.curMode() : 'plan'; },
  };
  window.TDM = TDM;

  /* Inline handlers of the site markup became data-on-<event>="Obj.fn" + data-on-<event>-args="…" (strict CSP). */
  function parseArgs(src, el, ev) {
    const out = []; let cur = ''; let q = null;
    for (const ch of String(src || '')) {
      if (q) { if (ch === q) q = null; cur += ch; continue; }
      if (ch === "'" || ch === '"') { q = ch; cur += ch; continue; }
      if (ch === ',') { out.push(cur.trim()); cur = ''; continue; }
      cur += ch;
    }
    if (cur.trim()) out.push(cur.trim());
    return out.map((a) => {
      if (a === 'this') return el;
      if (a === 'event') return ev;
      if (a.startsWith('this.')) return el[a.slice(5)];
      if (/^(['"]).*\1$/.test(a)) return a.slice(1, -1);
      if (/^-?\d+(\.\d+)?$/.test(a)) return Number(a);
      if (a === 'true' || a === 'false') return a === 'true';
      return undefined;
    });
  }
  function dispatchInline(ev) {
    const attr = 'data-on-' + ev.type;
    const el = ev.target && ev.target.closest ? ev.target.closest('[' + attr + ']') : null;
    if (!el) return;
    if (ev.type === 'submit') ev.preventDefault();
    const [obj, fn] = String(el.getAttribute(attr)).split('.');
    const target = window[obj];
    if (!target || typeof target[fn] !== 'function') return;
    target[fn](...parseArgs(el.getAttribute(attr + '-args'), el, ev));
  }
  ['click', 'change', 'input', 'keydown', 'pointerdown', 'submit'].forEach((t) => document.addEventListener(t, dispatchInline));

  // site window.render: the tools wrap it (sentence-part colours) — the app calls it after every page draw
  if (typeof window.render !== 'function') window.render = function () { if (window.Tutor && typeof window.Tutor.sync === 'function') window.Tutor.sync(); };

  void today;
  return { S, saveData, render, rememberLearningError, navigateApp, isOwnerAccount, isGlobalContentAdmin, appConfirm, hasPremiumAccess, openPremiumPlans, safeText, ownerAIClientMessageId, authTokens, setAppSetting, normalizeFavorite, setFavoriteRating, apiRequest, fetch: shimFetch, TDM };
}
